<?php ob_start(); ?><p class="eyebrow">Administration</p><h1><?= e($heading) ?></h1><form method="post" enctype="multipart/form-data" class="form-grid"><?= csrf_field() ?><?php foreach ($fields as $field): $value=$record[$field['name']]??''; ?><div class="field <?= !empty($field['full'])?'full':'' ?>"><label for="<?= e($field['name']) ?>"><?= e($field['label']) ?></label><?php if (($field['type']??'')==='textarea'): ?><textarea id="<?= e($field['name']) ?>" name="<?= e($field['name']) ?>"><?= e($value) ?></textarea><?php elseif (($field['type']??'')==='select'): ?><select id="<?= e($field['name']) ?>" name="<?= e($field['name']) ?>"><?php foreach ($field['options'] as $key=>$label): ?><option value="<?= e((string)$key) ?>" <?= (string)$value===(string)$key?'selected':'' ?>><?= e($label) ?></option><?php endforeach; ?></select><?php elseif (($field['type']??'')==='checkbox'): ?><input id="<?= e($field['name']) ?>" type="checkbox" name="<?= e($field['name']) ?>" value="1" <?= $value?'checked':'' ?>><?php else: ?><input id="<?= e($field['name']) ?>" type="<?= e($field['type']??'text') ?>" name="<?= e($field['name']) ?>" value="<?= ($field['type']??'')==='file'?'':e($value) ?>" <?= ($field['type']??'')==='file'?'accept="image/jpeg,image/png,image/webp"':'' ?>><?php endif; ?></div><?php endforeach; ?><div class="field full"><button>Save changes</button></div></form><?php $adminContent=ob_get_clean(); require ROOT.'/app/views/admin/shell.php'; ?>

